def fixed(t):
 out=[]
 for n in t[1:]:
  if isinstance(n,list):
   tag=V.atom(n[0])
   if tag in ['segment','arc','via','gr_poly']:continue
   if tag=='zone':n=[x for x in n if not (isinstance(x,list) and V.atom(x[0]) in ['filled_polygon','fill_segments'])]
   if tag=='footprint':n=n[:2]+sorted(n[2:],key=lambda z:str(V.canonical(z)))
  out.append(V.canonical(n))
 return sorted(out,key=str)
